"""PlotTwist C3 Space: bootstrap the unchanged, bundled coursework source.

Readable source: https://github.com/by-aseel/PlotTwist/tree/main/c3_business_assistant
The bundle contains only application modules, CSS, and fictional business files.
It contains no API key, customer database, or environment file.
"""
from pathlib import Path
import argparse
import base64
import io
import os
import sys
import zipfile

BUNDLE = ''
RUNTIME = Path(__file__).resolve().parent / '.plottwist-runtime'
RUNTIME.mkdir(exist_ok=True)
with zipfile.ZipFile(io.BytesIO(base64.b64decode(BUNDLE))) as archive:
    for item in archive.infolist():
        if not (RUNTIME / item.filename).resolve().is_relative_to(RUNTIME.resolve()):
            raise ValueError('Invalid application bundle path')
    archive.extractall(RUNTIME)
sys.path.insert(0, str(RUNTIME))
os.environ.setdefault('GRADIO_ANALYTICS_ENABLED', 'False')
from interface import create_app

if __name__ == '__main__':
    parser = argparse.ArgumentParser(description='PlotTwist C3 Hugging Face Space')
    parser.add_argument('--mode', choices=['auto', 'demo', 'live'], default=os.getenv('PLOTTWIST_MODE', 'auto'))
    parser.add_argument('--host', default=os.getenv('GRADIO_SERVER_NAME', '0.0.0.0' if os.getenv('SPACE_ID') else '127.0.0.1'))
    parser.add_argument('--port', type=int, default=int(os.getenv('PORT', '7860')))
    args = parser.parse_args()
    demo = create_app(mode=args.mode)
    demo.queue(default_concurrency_limit=4).launch(server_name=args.host, server_port=args.port, share=False, show_error=False)
